CREATE TABLE "public"."threshold" (
  "id"        bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "critical"  real   NOT NULL,
  "low_stock" real   NOT NULL,
  CONSTRAINT "threshold_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."threshold"
  ENABLE ROW LEVEL SECURITY;

CREATE POLICY "app_all_threshold" ON "public"."threshold"
  FOR ALL
  TO "anon", "authenticated"
  USING (true)
  WITH CHECK (true);

REVOKE ALL ON SEQUENCE "public"."threshold_id_seq" FROM "anon";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."threshold_id_seq" TO "anon";

REVOKE ALL ON SEQUENCE "public"."threshold_id_seq" FROM "authenticated";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."threshold_id_seq" TO "authenticated";

REVOKE ALL ON SEQUENCE "public"."threshold_id_seq" FROM "postgres";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."threshold_id_seq" TO "postgres";

REVOKE ALL ON SEQUENCE "public"."threshold_id_seq" FROM "service_role";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."threshold_id_seq" TO "service_role";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."threshold" TO "anon", "authenticated";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."threshold" TO "service_role";

REVOKE ALL ON TABLE "public"."threshold" FROM "postgres";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."threshold" TO "postgres";
